import type { AiGateway } from "./gateway";
import type { PromptRegistry } from "./prompts";

/**
 * Advisory narrative (Stage 04): a plain-language summary of a research package's FACTS (assessment, verdict classes, flag codes). It is generated by the hosted model, validated against a
 * closed shape, and returned SEPARATELY. It has no access to the package, so it cannot alter the assessment, a verdict, a score or a halt; absent or invalid it is simply null.
 */
export const NARRATIVE_TASK = "research_narrative";
export interface NarrativeFacts { assessment: string; halted: boolean; verdictCounts: Record<string, number>; riskFlags: readonly string[]; missingRoles: readonly string[] }
export interface Narrative { summary: string }
export const isNarrative = (v: unknown): v is Narrative => typeof v === "object" && v !== null && !Array.isArray(v) && Object.keys(v).length === 1 && typeof (v as Narrative).summary === "string" && (v as Narrative).summary.length > 0 && (v as Narrative).summary.length <= 1200;

export function registerNarrativePrompt(prompts: PromptRegistry): void {
  prompts.register({
    id: "research-narrative", version: "1.0.0", task: NARRATIVE_TASK,
    system: "You summarise supplied research facts in plain language. Use only the facts given. Do not recommend trades, sizes, prices or actions. Reply with JSON: {\"summary\": string}.",
    template: "Assessment: {{assessment}}. Halted: {{halted}}. Verdict counts: {{verdictCounts}}. Risk flags: {{riskFlags}}. Missing roles: {{missingRoles}}.",
    variables: ["assessment", "halted", "verdictCounts", "riskFlags", "missingRoles"],
  });
}
export async function narrate(gateway: AiGateway, facts: NarrativeFacts, userId: string | null = null): Promise<{ summary: string; advisory: true; provider: string; model: string; promptVersion: string } | null> {
  const r = await gateway.run<Narrative>({
    task: NARRATIVE_TASK, userId, guard: isNarrative,
    vars: { assessment: facts.assessment, halted: facts.halted, verdictCounts: JSON.stringify(facts.verdictCounts), riskFlags: facts.riskFlags.slice(0, 20).join(",") || "none", missingRoles: facts.missingRoles.join(",") || "none" },
  });
  return r.ok ? { summary: r.value.summary, advisory: true, provider: r.provenance.provider, model: r.provenance.model, promptVersion: r.provenance.promptVersion } : null;
}
